program = '''from collections import Counter

def transform(grid):
    counts = Counter(v for row in grid for v in row)
    background, foreground = counts.most_common(2)[0][0], counts.most_common(2)[1][0]
    if counts[foreground] == 1:
        mapping = {background: foreground, foreground: 0}
    else:
        mapping = {background: 0, foreground: background}
    return [[mapping[v] for v in row] for row in grid]
'''
